    id: str
    text: str

article.sections.12.blocks.7.text:
def grade_documents(
    state: GraphState,
    judge: Callable[[str, str], Literal["yes", "no"]],
) -> GraphState:
    kept: list[Document] = []
    search: Literal["yes", "no"] = "no"
    for document in state["documents"]:
        if judge(state["question"], document["text"]) == "yes":
            kept.append(document)
        else:
            search = "yes"
    return {
        **state,
        "documents": kept,
        "search": search,
        "steps": [*state["steps"], "grade_document_retrieval"],
    }

